mapper.select:
WITH resident_stats AS ( SELECT ra.room_id, COUNT(*) AS active_residents, SUM(CASE WHEN ra.bed_id IS NULL THEN 1 ELSE 0 END) AS unknown_beds FROM room_assignment ra WHERE ra.assignment_status = 'ACTIVE' AND ra.room_id IN
#{roomId}
GROUP BY ra.room_id ), bed_stats AS ( SELECT bed.room_id, SUM(CASE WHEN bed.operational_status = 'ENABLED' AND occupied.id IS NULL THEN 1 ELSE 0 END) AS available_beds FROM bed LEFT JOIN room_assignment occupied ON occupied.room_id = bed.room_id AND occupied.bed_id = bed.id AND occupied.assignment_status = 'ACTIVE' WHERE bed.room_id IN
#{roomId}
GROUP BY bed.room_id ) SELECT r.id, r.room_number, r.room_type, r.capacity, r.gender_restriction, r.resident_scope, r.operational_status, r.state_version, f.floor_number, b.id AS building_id, b.building_code, b.building_name, COALESCE(residents.active_residents, 0) AS active_residents, COALESCE(residents.unknown_beds, 0) AS unknown_beds, COALESCE(beds.available_beds, 0) AS available_beds, conflict_lock.batch_id AS conflict_batch_id, conflict_batch.batch_name AS conflict_batch_name, conflict_lock.selection_mode AS conflict_selection_mode FROM room r JOIN dormitory_floor f ON f.id = r.floor_id JOIN dormitory_building b ON b.id = f.building_id LEFT JOIN resident_stats residents ON residents.room_id = r.id LEFT JOIN bed_stats beds ON beds.room_id = r.id LEFT JOIN active_batch_room_lock conflict_lock ON conflict_lock.room_id = r.id AND conflict_lock.batch_id <> #{batchId} LEFT JOIN selection_batch conflict_batch ON conflict_batch.id = conflict_lock.batch_id WHERE r.id IN
#{roomId}
ORDER BY r.id
